    "telegramWebhook.handle": {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": ({
                        /** @constant */
                        status: "success";
                    } | {
                        /** @constant */
                        status: "no_change";
                    } | {
                        /** @constant */
                        status: "invalid_transition";
                    } | {
                        /** @constant */
                        status: "cannot_cancel";
                    } | {
                        /** @constant */
                        status: "forbidden";
                    } | {
                        /** @constant */
                        status: "invalid_reason";
                    } | {
                        /** @constant */
                        status: "choose_reason";
                    } | {
                        /** @constant */
                        status: "back";
                    } | {
                        /** @constant */
                        status: "error";
                        /** @constant */
                        message: "Invalid token";
                    } | {
                        /** @constant */
                        status: "unhandled_action";
                    } | {
                        /** @constant */
                        status: "error";
                        /** @constant */
                        message: "Order not found";
                    } | {
                        /** @constant */
                        status: "error";
                        /** @constant */
                        message: "Expired token";
                    } | {
                        /** @constant */
                        status: "error";
                        /** @constant */
                        message: "Already used";
                    }) | {
                        /** @constant */
                        status: "ignored";
                    } | {
                        status: string;
                    };
                };
            };
        };
    };
